  const navEventos=document.getElementById('moduloEventos');
  const navEmpleo=document.getElementById('moduloEmpleo');
  const navActividades=document.getElementById('moduloActividades');
  const frame=document.getElementById('moduloCentralFrame');

  // Archivos centrales. Si cambian de carpeta, sólo se modifican estas cuatro rutas.
  const MODULOS={
    guia:{nav:navGuia,url:'./anunciantes.html',label:'Guía',protegido:false},
    promos:{nav:navPromos,url:'./promos.html',label:'Promos',protegido:true},
    eventos:{nav:navEventos,url:'./eventos.html',label:'Eventos',protegido:true},
    actividades:{nav:navActividades,url:'./actividades.html',label:'Actividades',protegido:true},
    empleo:{nav:navEmpleo,url:'./empleo.html',label:'Empleo',protegido:false}
  };

  let moduloActual='';
  let tokenCarga=0;
  let resolverInicialUsado=false;

  function setActivo(key){
    Object.values(MODULOS).forEach(m=>m.nav?.classList.remove('activo'));
    MODULOS[key]?.nav?.classList.add('activo');
  }

  function contextoUrl(base){
    const u=new URL(base,new URL('/plataforma/',window.location.origin));
    const recibidos=new URLSearchParams(window.location.search);
    let ctx={};try{ctx=JSON.parse(localStorage.getItem('gld_ciudad_contexto')||'null')||{};}catch(_){}
    // No heredar ni un dato territorial si el contexto guardado es de otra ciudad.
    const ciudadUrl=String(recibidos.get('ciudad_id')||'').trim();
    if(ciudadUrl && String(ctx.ciudad_id||'').trim()!==ciudadUrl)ctx={};
    ['pais_id','provincia_id','ciudad_id','pais','provincia','ciudad'].forEach(k=>{
      const v=String(recibidos.get(k)||ctx[k]||'').trim();if(v)u.searchParams.set(k,v);
    });
    if(u.pathname.endsWith('/anunciantes.html')){
      for(const k of ['anunciante_id','sede_id'])if(recibidos.get(k))u.searchParams.set(k,recibidos.get(k));
    }
    return u.toString();
  }

  function guardarFiltroTarjeta_(link,key){
    try{
      if(key==='promos'){
        const raw=decodeURIComponent(String(link.dataset.promoFilter||''));
        const d=raw?JSON.parse(raw):null;
        if(d){d.ts=Date.now();localStorage.setItem('gld_promos_filter',JSON.stringify(d));}
      }else if(key==='eventos'){
        const raw=decodeURIComponent(String(link.dataset.eventFilter||''));
        const d=raw?JSON.parse(raw):null;
        if(d){d.ts=Date.now();localStorage.setItem('gld_eventos_filter',JSON.stringify(d));}
      }else if(key==='actividades'){
        const raw=decodeURIComponent(String(link.dataset.actividadFilter||''));
        const d=raw?JSON.parse(raw):null;
        if(d){d.ts=Date.now();localStorage.setItem('gld_actividades_filter',JSON.stringify(d));}
      }
    }catch(err){
      console.warn('No se pudo conservar el filtro de la tarjeta:',err);
    }
  }

  function gldScrollCarcasaArriba_(){
    const titulo=document.getElementById('titulo-principal');
    try{
      if(titulo) titulo.scrollIntoView({behavior:'smooth',block:'start'});
      else window.scrollTo({top:0,behavior:'smooth'});
    }catch(e){
      try{window.scrollTo(0,0);}catch(_){}
    }

    // Si la Carcasa está embebida en Jimdo, pedimos también al contenedor exterior
    // que coloque el iframe de Guía arriba.
    if(window.self!==window.top){
      try{window.frameElement?.scrollIntoView?.({behavior:'smooth',block:'start'});}catch(e){}
      try{
        window.parent.postMessage({
          type:'guialocal:scrollToSelector',
          selector:'#titulo-principal'
        },'*');
      }catch(e){}
    }
  }

  // El paginador pertenece al módulo; Carcasa sólo ubica el resultado debajo de sus filtros.
  window.gldScrollResultadosGuia_=function(){
    if(String(frame.dataset.modulo||'')!=='guia')return;
    try{
      const target=frame.contentDocument?.getElementById('destacadasBar')||
        frame.contentDocument?.getElementById('contenedor');
      if(!target)return;
      ajustarAltura();
      target.scrollIntoView({behavior:'smooth',block:'start'});
    }catch(e){}
  };

  function enlazarAccesosTarjetasGuia_(){
    if(String(frame.dataset.modulo||'')!=='guia') return;
    try{
      const doc=frame.contentDocument;
      if(!doc || doc.__gldAccesosTarjetasEnlazados) return;
      doc.__gldAccesosTarjetasEnlazados=true;

      doc.addEventListener('click',e=>{
        const paginador=e.target.closest?.(
          '#btnAnterior,#btnSiguiente,#paginationBar button,.pagination-bar button,[onclick*="irAPagina"],[onclick*="cambiarPagina"]'
        );
        if(paginador){
          setTimeout(window.gldScrollResultadosGuia_,80);
