          e.preventDefault();
          guardarFiltroTarjeta_(promo,'promos');
          cargarCentro('promos',{filtered:true,forzar:true,disparador:navPromos});
          return;
        }

        const evento=e.target.closest?.('a.eventos-activos-btn');
        if(evento){
          e.preventDefault();
          guardarFiltroTarjeta_(evento,'eventos');
          cargarCentro('eventos',{filtered:true,forzar:true,disparador:navEventos});
