        }
      });
    }catch(err){
      console.warn('No se pudieron enlazar accesos de tarjetas de Guía:',err);
    }
  }

  function ajustarAltura(){
    try{
      const doc=frame.contentDocument;
      const body=doc?.body;
      if(!doc || !body) return;

      let sentinel=doc.getElementById('__gldModuloAlturaSentinel');
      if(!sentinel){
        sentinel=doc.createElement('div');
        sentinel.id='__gldModuloAlturaSentinel';
        sentinel.setAttribute('aria-hidden','true');
        sentinel.style.cssText='display:block;width:1px;height:1px;margin:0;padding:0;border:0;clear:both;pointer-events:none;visibility:hidden;';
      }

      /*
        El módulo agrega y reemplaza contenido dinámicamente.
        El sentinel debe estar SIEMPRE al final real del body antes de medir.
        Si queda en una posición anterior, la Carcasa corta tarjetas y paginador.
      */
      if(sentinel.parentNode!==body || sentinel!==body.lastElementChild){
        body.appendChild(sentinel);
      }

      const bodyRect=body.getBoundingClientRect();
      const sRect=sentinel.getBoundingClientRect();
      const h=Math.max(1,Math.ceil(sRect.bottom-bodyRect.top));

      if(Math.abs((parseFloat(frame.style.height)||0)-h)>=2){
        frame.style.height=h+'px';
      }
      frame.style.minHeight='0';
      setTimeout(()=>window.gldRecalcularAlturaCarcasa?.(),0);
    }catch(e){}
  }

  frame?.addEventListener('load',()=>{
    ajustarAltura();
    enlazarAccesosTarjetasGuia_();
    try{
      frame.__gldRO?.disconnect?.();
      const doc=frame.contentDocument;
      if(doc && 'ResizeObserver' in window){
        const ro=new ResizeObserver(ajustarAltura);
        if(doc.documentElement) ro.observe(doc.documentElement);
        if(doc.body) ro.observe(doc.body);
        frame.__gldRO=ro;
      }
    }catch(e){}
    setTimeout(()=>{ajustarAltura();enlazarAccesosTarjetasGuia_();},250);
    setTimeout(()=>{ajustarAltura();enlazarAccesosTarjetasGuia_();},1000);
    setTimeout(enlazarAccesosTarjetasGuia_,2200);
  });

  window.addEventListener('message',(e)=>{
    const d=e.data||{};

    if(d && (d.type==='guialocal:scrollToSelector' || d.tipo==='guialocal:scrollToSelector')){
      gldScrollCarcasaArriba_();
    }

    if(d && d.tipo==='alturaIframeGLD' && Number(d.altura)>0){
      try{
        if(frame.contentDocument) ajustarAltura();
        else{
          frame.style.height=Math.max(1,Number(d.altura))+'px';
          frame.style.minHeight='0';
        }
      }catch(err){
        frame.style.height=Math.max(1,Number(d.altura))+'px';
        frame.style.minHeight='0';
      }
    }
    if(d && d.tipo==='gldModuloEstado' && String(d.modulo||'')===String(frame.dataset.modulo||'')){
      if(d.estado==='ready'){
        const token=Number(frame.dataset.cargaToken||0);
        finalizarCarga(token,frame.dataset.cargaInicial==='1');
      }else if(d.estado==='error'){
        const box=document.getElementById('gldBloqueoTotal');
        const txt=document.getElementById('gldBloqueoTexto');
        if(box) box.classList.add('error');
        if(txt) txt.textContent=String(d.detalle||'La información está demorando más de lo habitual.');
        const rb=document.getElementById('gldBloqueoReintentar');
        if(rb){
          const mk=String(frame.dataset.modulo||'');
          const ml=MODULOS[mk]?.label || '';
          rb.textContent=ml ? `Reintentar ${ml.toLowerCase()}` : 'Reintentar';
        }
      }
    }
  });

  function finalizarCarga(miToken,esInicial){
    if(miToken!==tokenCarga) return;
    gldSetModuloCargando('',false);
    ajustarAltura();
    setTimeout(()=>window.gldRecalcularAlturaCarcasa?.(),0);
    setTimeout(()=>window.gldRecalcularAlturaCarcasa?.(),250);
    if(esInicial && !resolverInicialUsado){
      resolverInicialUsado=true;
      try{window.gldResolverCentroInicial?.();}catch(e){}
    }
  }

  function cargarCentro(key,options={}){
    key=String(key||'guia').toLowerCase();
    const mod=MODULOS[key]||MODULOS.guia;

    if(mod.protegido && !gldRequireSubscriber(options.disparador||null,options)) return false;
    // La carga inicial de Guía forma parte del bloqueo general y debe poder arrancar.
    if(gldModuloCargando && !(options.inicial && key==='guia')) return false;

    const esInicial=!!options.inicial;
    const forzar=!!options.forzar;
    const filtered=!!options.filtered;

    setActivo(key);
    moduloActual=key;

    if(!forzar && frame.dataset.modulo===key && !filtered){
      if(esInicial && !resolverInicialUsado){
        resolverInicialUsado=true;
        try{window.gldResolverCentroInicial?.();}catch(e){}
      }
      return true;
    }

    gldSetModuloCargando(key,true,'Cargando '+mod.label+'...');
    const miToken=++tokenCarga;
    frame.dataset.modulo=key;
    frame.dataset.cargaToken=String(miToken);
    frame.dataset.cargaInicial=esInicial?'1':'0';
    frame.title=mod.label+' de la ciudad';

    const esperaReadyInterno = ['guia','promos','eventos','actividades'].includes(key);
    const onload=()=>{
      frame.removeEventListener('load',onload);
      if(!esperaReadyInterno) finalizarCarga(miToken,esInicial);
    };
    frame.addEventListener('load',onload);

    setTimeout(()=>{
      if(miToken!==tokenCarga || !esperaReadyInterno || !gldModuloCargando) return;
      const box=document.getElementById('gldBloqueoTotal');
      const txt=document.getElementById('gldBloqueoTexto');
      if(box) box.classList.add('error');
      if(txt) txt.textContent='La información está demorando más de lo habitual.';
      const rb=document.getElementById('gldBloqueoReintentar');
      if(rb) rb.textContent=`Reintentar ${String(mod.label||'').toLowerCase()}`;
    },30000);

    // Hosting revalida el HTML con ETag. Conservar la URL permite reutilizar su cuerpo.
    const destino=contextoUrl(mod.url);
    frame.src=destino;
    return true;
  }

  window.mostrarModuloCiudad=function(key,options={}){
    return cargarCentro(key,options);
  };

  navGuia?.addEventListener('click',e=>{e.preventDefault();cargarCentro('guia',{disparador:e.currentTarget});});
